def to_bytes_py2(s):
    # Accepts string with either python repr (\x..) or actual bytes
    import binascii
    if isinstance(s, bytes):
        return s
    if s.startswith('b"') or s.startswith('b\''):
        s = eval(s)
    try:
        return binascii.unhexlify(s)
    except Exception:
        pass
    # fallback: parse python escape str
